const APP_VERSION = "5.97";
window.APP_VERSION = APP_VERSION;
window.APP_VERSION_176 = APP_VERSION;
window.APP_VERSION_181 = APP_VERSION;
function setAppVersionUI(){
  try{ document.title = "מעקב עבודה - גרסה " + APP_VERSION; }catch(e){}
  try{ document.querySelectorAll(".secret,#secretTap").forEach(el => { el.textContent = "גרסה " + APP_VERSION; }); }catch(e){}
  try{ document.querySelectorAll("[data-app-version],#appVersion,#versionLabel").forEach(el => { el.textContent = APP_VERSION; }); }catch(e){}
}
setAppVersionUI();
window.addEventListener("DOMContentLoaded", setAppVersionUI);
window.addEventListener("load", setAppVersionUI);

