async function ensureDefaultPriceList(){
  // יוצר מחירון ברירת מחדל רק אם אין פריטים פעילים בכלל.
  // לא מוסיף שוב אם כבר קיימים פריטים, כדי למנוע כפילויות.
  const snap = await db.collection("priceList").limit(1).get();
  if(!snap.empty) {
    // v5.22 FIX:
    // עובד רגיל לא אמור להריץ ניקוי כפילויות מחירון בטעינה, כי זו פעולת כתיבה שגורמת permission-denied.
    // הניקוי נשאר זמין לאדמין דרך הכפתור הייעודי בלבד.
    try{
      if(session && session.role === "admin") await cleanupDuplicatePriceList();
    }catch(e){
      console.warn("cleanupDuplicatePriceList skipped in startup:", e && (e.code || e.message) ? (e.code || e.message) : e);
    }
    return;
  }
  const batch=db.batch();
  defaultPriceList.forEach(item=>{
    const ref=db.collection("priceList").doc();
    batch.set(ref,{...item,createdAt:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()});
  });
  await batch.commit();
}

async function cleanupDuplicatePriceList(){
  try{
    const snap = await db.collection("priceList").get();
    const seen = {};
    const duplicates = [];
    snap.docs.forEach(doc=>{
      const d = doc.data();
      const key = `${String(d.name||"").trim()}|${Number(d.price||0)}|${d.inputMode||"qty"}`;
      if(!seen[key]){
        seen[key] = doc;
      }else{
        duplicates.push(doc);
      }
    });
    if(!duplicates.length) return;
    const batch = db.batch();
    duplicates.forEach(doc=>{
      batch.update(doc.ref,{active:false,duplicateHidden:true,updatedAt:firebase.firestore.FieldValue.serverTimestamp()});
    });
    await batch.commit();
  }catch(e){
    console.error("cleanupDuplicatePriceList failed", e);
  }
}

async function loadPriceList(){const snap=await db.collection("priceList").get();priceList=snap.docs.map(d=>({id:d.id,...d.data()})).map(x=>({...x,inputMode:x.inputMode||"qty"})).filter(x=>x.active!==false);
    const uniqueMap={};
    priceList.forEach(item=>{
      const key=`${String(item.name||"").trim()}|${Number(item.price||0)}|${item.inputMode||"qty"}`;
      if(!uniqueMap[key]) uniqueMap[key]=item;
    });
    priceList=Object.values(uniqueMap).sort((a,b)=>Number(a.order||0)-Number(b.order||0))}
