/* ===== v3.9: Stable installation item checklist in search, using global let priceList correctly ===== */
(function(){
  window.selectedWorkerPriceSearchItemsV38 = window.selectedWorkerPriceSearchItemsV38 || new Set();

  function byId(id){ return document.getElementById(id); }
  function safeEscV38(s){
    try{ return typeof esc === 'function' ? esc(s) : String(s||'').replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]||c;}); }
    catch(e){ return String(s||''); }
  }
  function currentSearchTypeV38(){
    var el=byId('searchType');
    return el ? String(el.value||'') : '';
  }
  function getSelectedPriceNamesV38(){
    return Array.from(window.selectedWorkerPriceSearchItemsV38 || []);
  }
  window.clearWorkerPriceSearchV22 = function(){
    window.selectedWorkerPriceSearchItemsV38 = new Set();
    document.querySelectorAll('#priceSearchListV22 input[type="checkbox"]').forEach(function(cb){ cb.checked=false; });
    updatePriceSearchNoteV38();
  };
  function updatePriceSearchNoteV38(){
    var note=byId('priceSearchNoteV22');
    if(!note) return;
    var type=currentSearchTypeV38();
    if(type !== 'install'){
      note.textContent='בחר סוג עבודה: התקנות כדי לפתוח את הצ׳קליסט';
      return;
    }
    var count=getSelectedPriceNamesV38().length;
    note.textContent=count ? ('נבחרו '+count+' פריטי התקנה לסינון') : 'בחר פריטי התקנה לסינון, או השאר ריק כדי לראות את כל ההתקנות';
  }
  function getPriceListForSearchV39(){
    // priceList מוגדר בקובץ הראשי עם let, לכן הוא לא נמצא על window.
    // לכן קודם קוראים למשתנה הגלובלי עצמו, ורק אם לא קיים נופלים ל-window.
    try{
      if(typeof priceList !== 'undefined' && Array.isArray(priceList) && priceList.length){
        return priceList;
      }
    }catch(e){}
    try{
      if(Array.isArray(window.priceList) && window.priceList.length){
        return window.priceList;
      }
    }catch(e){}
    return [];
  }

  function renderPriceSearchListV38(){
    var list=byId('priceSearchListV22');
    if(!list) return;
    var items=getPriceListForSearchV39().filter(function(p){ return p && p.active !== false; });
    if(!items.length){
      list.innerHTML='<div class="muted">לא נטענו פריטי מחירון. סגור ופתח את החיפוש שוב, או רענן את המסך.</div>';
      return;
    }
    list.innerHTML='';
    items.forEach(function(p){
      var name=String(p.name||'');
      var id='priceSearchV38_'+String(p.id||name).replace(/[^a-zA-Z0-9_\-א-ת]/g,'_');
      var label=document.createElement('label');
      label.className='price-search-item-v22';
      label.setAttribute('for', id);
      label.innerHTML='<input id="'+id+'" type="checkbox" data-price-name="'+safeEscV38(name)+'"> <span>'+safeEscV38(name)+'</span>';
      var cb=label.querySelector('input');
      cb.checked=(window.selectedWorkerPriceSearchItemsV38 || new Set()).has(name);
      cb.addEventListener('change', function(){
        if(!window.selectedWorkerPriceSearchItemsV38) window.selectedWorkerPriceSearchItemsV38=new Set();
        if(cb.checked) window.selectedWorkerPriceSearchItemsV38.add(name);
        else window.selectedWorkerPriceSearchItemsV38.delete(name);
        updatePriceSearchNoteV38();
      });
      list.appendChild(label);
    });
    updatePriceSearchNoteV38();
  }
  window.renderWorkerPriceSearchV38 = renderPriceSearchListV38;

  window.onWorkerSearchTypeChangeV22 = async function(){
    var box=byId('workerPriceSearchBoxV22');
    var type=currentSearchTypeV38();
    if(!box) return;
    if(type === 'install'){
      box.classList.remove('hidden');
      var list=byId('priceSearchListV22');
      if(list) list.innerHTML='<div class="muted">טוען פריטי מחירון...</div>';
      try{
        if(!getPriceListForSearchV39().length && typeof loadPriceList === 'function'){
          await loadPriceList();
        }
      }catch(e){
        console.warn('loadPriceList for search failed',e);
      }
      renderPriceSearchListV38();
    }else{
      box.classList.add('hidden');
      window.clearWorkerPriceSearchV22();
    }
  };

  var originalGetFilteredEntriesV38 = window.getFilteredEntries;
  window.getFilteredEntries = function(){
    var arr;
    if(typeof originalGetFilteredEntriesV38 === 'function') arr = originalGetFilteredEntriesV38.apply(this, arguments);
    else arr = Array.isArray(window.monthEntries) ? window.monthEntries.slice() : [];
    if(currentSearchTypeV38() !== 'install') return arr;
    var selected=getSelectedPriceNamesV38();
    if(!selected.length) return arr;
    return arr.filter(function(e){
      if(!e || e.workType !== 'install') return false;
      var items=e.items || [];
      return selected.every(function(name){
        return items.some(function(i){ return String(i.name||'') === String(name); });
      });
    });
  };

  var originalClearSearchV38 = window.clearSearch;
  window.clearSearch = function(){
    if(typeof originalClearSearchV38 === 'function') originalClearSearchV38.apply(this, arguments);
    window.clearWorkerPriceSearchV22();
    var box=byId('workerPriceSearchBoxV22');
    if(box) box.classList.add('hidden');
  };

  var originalToggleSearchPanelV38 = window.toggleSearchPanel;
  window.toggleSearchPanel = async function(){
    if(typeof originalToggleSearchPanelV38 === 'function') originalToggleSearchPanelV38.apply(this, arguments);
    setTimeout(function(){ window.onWorkerSearchTypeChangeV22 && window.onWorkerSearchTypeChangeV22(); },50);
  };

  document.addEventListener('DOMContentLoaded', function(){
    var st=byId('searchType');
    if(st) st.addEventListener('change', function(){ window.onWorkerSearchTypeChangeV22(); });
    setTimeout(function(){ window.onWorkerSearchTypeChangeV22 && window.onWorkerSearchTypeChangeV22(); },150);
  });
  window.addEventListener('load', function(){ setTimeout(function(){ window.onWorkerSearchTypeChangeV22 && window.onWorkerSearchTypeChangeV22(); },250); });
})();
;
/* ===== v4.1: Save feedback helper ===== */
function showEntryFeedbackV41(type, amount){
  try{
    var isService = type === 'service';
    var baseLabel = isService ? 'קריאת השירות נשמרה' : 'ההתקנה נשמרה';
    var online = true;
    try{ online = navigator.onLine !== false; }catch(_e){}
    var label = online
      ? (baseLabel + ' בהצלחה ✅')
      : (baseLabel + ' מקומית ✅');
    var syncLine = online
      ? 'המסך עודכן ואפשר להמשיך להזין עבודה חדשה.'
      : 'אין חיבור כרגע — הנתונים יסתנכרנו אוטומטית כשהאפליקציה תחזור לאונליין.';
    var amountText = '';
    try{ amountText = typeof money === 'function' ? money(amount || 0) : ('₪' + Number(amount || 0)); }catch(e){ amountText = ''; }
    var html = '<div class="save-feedback-v41">' + label + (amountText ? '<br><span>סכום שנשמר: ' + amountText + '</span>' : '') + '<br><span>' + syncLine + '</span></div>';
    var entry = document.getElementById('entryMsg');
    if(entry) entry.innerHTML = html;

    var old = document.getElementById('saveToastV41');
    if(old) old.remove();
    var toast = document.createElement('div');
    toast.id = 'saveToastV41';
    toast.className = 'save-toast-v41';
    toast.textContent = label + (amountText ? ' · ' + amountText : '');
    document.body.appendChild(toast);
    setTimeout(function(){ if(toast && toast.parentNode) toast.remove(); }, 2600);
  }catch(e){
    try{
      var entryFallback = document.getElementById('entryMsg');
      if(entryFallback) entryFallback.innerHTML = '<div class="notice">נשמר בהצלחה ✅</div>';
    }catch(_e){}
  }
}
;
/* ===== v4.2: Reset forms, history warnings and return to work-type choice after successful save ===== */
function resetEntryFormsAfterSaveV42(){
  try{
    [
      'sCustomer','sAddress','sNotes',
      'iCustomer','iAddress','iNotes'
    ].forEach(function(id){
      var el=document.getElementById(id);
      if(el) el.value='';
    });

    ['sCustomerHistory','iCustomerHistory'].forEach(function(id){
      var el=document.getElementById(id);
      if(el) el.innerHTML='';
    });

    var returnCall=document.getElementById('sReturnCall');
    if(returnCall) returnCall.checked=false;

    var tpl=document.getElementById('installTemplateSelect');
    if(tpl) tpl.value='';

    try{
      if(Array.isArray(priceList)){
        priceList.forEach(function(p){
          var el=document.getElementById('qty_'+p.id);
          if(!el) return;
          if((p.inputMode||'qty')==='check') el.checked=false;
          else el.value='';
        });
      }
    }catch(e){}

    try{ if(typeof updateServicePreview==='function') updateServicePreview(); }catch(e){}
    try{ if(typeof updateInstallPreview==='function') updateInstallPreview(); }catch(e){}

    try{ selectedType=null; }catch(e){}
    var serviceForm=document.getElementById('serviceForm');
    var installForm=document.getElementById('installForm');
    var serviceBtn=document.getElementById('serviceBtn');
    var installBtn=document.getElementById('installBtn');
    if(serviceForm) serviceForm.classList.add('hidden');
    if(installForm) installForm.classList.add('hidden');
    if(serviceBtn) serviceBtn.classList.remove('active');
    if(installBtn) installBtn.classList.remove('active');
  }catch(e){
    console.warn('resetEntryFormsAfterSaveV42 failed', e);
  }
}

async function addService(){
  const customerNumber=val('sCustomer'), address=val('sAddress'), notes=val('sNotes'), isReturnCall=$('sReturnCall')&&$('sReturnCall').checked;
  const amount=isReturnCall?0:SERVICE_PRICE;
  if(!customerNumber||!/^\d+$/.test(customerNumber))return $('entryMsg').innerHTML='<p class="danger">חובה למלא מספר לקוח בספרות בלבד.</p>';
  if(!address)return $('entryMsg').innerHTML='<p class="danger">חובה למלא כתובת.</p>';

  await db.collection('workEntries').add({
    workerId:viewedWorker.id,
    workerName:viewedWorker.name,
    authUid:viewedWorker.authUid||currentAuthUid(),
    date:selectedDate,
    workType:'service',
    description:isReturnCall?'קריאת שירות חוזרת':'קריאת שירות',
    customerNumber,address,notes,isReturnCall,amount,
    createdAt:firebase.firestore.FieldValue.serverTimestamp()
  });

  resetEntryFormsAfterSaveV42();
  showEntryFeedbackV41('service', amount);
  await loadMonth();
  resetEntryFormsAfterSaveV42();
  showEntryFeedbackV41('service', amount);
}

async function addInstall(){
  const customerNumber=val('iCustomer'), address=val('iAddress'), notes=val('iNotes');
  if(!customerNumber||!/^\d+$/.test(customerNumber))return $('entryMsg').innerHTML='<p class="danger">חובה למלא מספר לקוח בספרות בלבד.</p>';
  if(!address)return $('entryMsg').innerHTML='<p class="danger">חובה למלא כתובת.</p>';

  let items=[], total=0;
  priceList.forEach(p=>{
    const el=$('qty_'+p.id);
    let q=0;
    if(el)q=(p.inputMode||'qty')==='check'?(el.checked?1:0):Number(el.value||0);
    if(q>0){
      items.push({id:p.id,name:p.name,price:Number(p.price||0),quantity:q,inputMode:p.inputMode||'qty',total:q*Number(p.price||0)});
      total+=q*Number(p.price||0);
    }
  });
  if(!items.length)return $('entryMsg').innerHTML='<p class="danger">חובה לבחור לפחות פריט אחד.</p>';

  await db.collection('workEntries').add({
    workerId:viewedWorker.id,
    workerName:viewedWorker.name,
    authUid:viewedWorker.authUid||currentAuthUid(),
    date:selectedDate,
    workType:'install',
    description:'התקנה',
    customerNumber,address,notes,items,amount:total,
    createdAt:firebase.firestore.FieldValue.serverTimestamp()
  });

  resetEntryFormsAfterSaveV42();
  showEntryFeedbackV41('install', total);
  await loadMonth();
  resetEntryFormsAfterSaveV42();
  showEntryFeedbackV41('install', total);
}
;
/* ===== v4.4: תיקון הרשמה עצמית וחזרה למסך כניסה =====
   המטרה: לא להציג שגיאת Security שקרית כשהעובד כבר נוצר,
   לא להשאיר את המשתמש תקוע במסך הרשמה, ולא להחזיר כלי Security ישנים לאדמין.
*/
(function(){
  window.APP_VERSION = APP_VERSION;
  try{ if(typeof APP_VERSION !== "undefined"){} }catch(e){}
  try{ document.title = "מעקב עבודה - גרסה " + APP_VERSION; }catch(e){}

  function byId(id){ return document.getElementById(id); }
  function safeHide(id){ var el=byId(id); if(el) el.classList.add('hidden'); }
  function safeShow(id){ var el=byId(id); if(el) el.classList.remove('hidden'); }
  function setHtml(id,html){ var el=byId(id); if(el) el.innerHTML=html; }
  function setTextSafe(id,t){ var el=byId(id); if(el) el.textContent=t; }
  function getValSafe(id){ var el=byId(id); return el ? String(el.value||'').trim() : ''; }
  function normalizeV43(s){ return String(s||'').trim().toLowerCase(); }
  function workerIdFromUsernameV43(k){ return 'worker_'+String(k||'').replace(/[^a-z0-9_\-א-ת]/gi,'_'); }
  function isPermissionErrorV43(e){
    var code=String((e&&e.code)||'').toLowerCase();
    var msg=String((e&&e.message)||e||'').toLowerCase();
    return code.includes('permission') || msg.includes('permission') || msg.includes('missing or insufficient permissions');
  }
  async function sha256V43(str){
    if(typeof sha256 === 'function') return await sha256(str);
    const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(str));
    return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
  }
  function heDateV43(s){ try{ return typeof heDate==='function'?heDate(s):s; }catch(e){ return s; } }
  function todayPlusDaysV43(days){
    try{ if(typeof addDaysToDate==='function') return addDaysToDate(days); }catch(e){}
    var d=new Date(); d.setDate(d.getDate()+Number(days||90));
    var p=n=>String(n).padStart(2,'0');
    return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate());
  }
  function cleanEmailV43(email){
    try{ if(typeof cleanEmailV168==='function') return cleanEmailV168(email); }catch(e){}
    return String(email||'').trim().toLowerCase();
  }
  function validEmailV43(email){
    try{ if(typeof isValidEmailV168==='function') return isValidEmailV168(email); }catch(e){}
    return !email || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }
  function authEmailV43(username,recoveryEmail){
    try{ if(typeof effectiveAuthEmailV168==='function') return effectiveAuthEmailV168(username,recoveryEmail); }catch(e){}
    if(recoveryEmail) return recoveryEmail;
    try{ if(typeof authEmailFromUsername==='function') return authEmailFromUsername(username); }catch(e){}
    return String(username||'worker').replace(/[^a-z0-9_\-]/gi,'_')+'@work-monitor.local';
  }
  function firebaseAuthReadyV43(){
    try{ return !!(window.firebase && firebase.auth && auth); }catch(e){ return false; }
  }
  function setRegisterBusyV43(isBusy){
    var btn=[].slice.call(document.querySelectorAll('#registerView button')).find(function(b){
      return String(b.getAttribute('onclick')||'').includes('registerWorker');
    });
    if(btn){ btn.disabled=!!isBusy; btn.textContent=isBusy?'יוצר משתמש...':'פתח משתמש ניסיון'; }
  }
  window.showWorkerLogin = function(){
    try{ if(typeof clearLoginFields==='function') clearLoginFields(); }catch(e){}
    ['startupView','workerLoginView','registerView','expiredView','adminLoginView','adminView','workerView'].forEach(safeHide);
    safeShow('workerLoginView');
    safeHide('logoutBtn');
    setTextSafe('userLine','לא מחובר');
    setTextSafe('workerLoginMsg','');
    try{ var wu=byId('workerUsername'); if(wu) setTimeout(function(){wu.focus();},30); }catch(e){}
    return false;
  };
  window.showRegister = function(){
    try{ if(typeof clearLoginFields==='function') clearLoginFields(); }catch(e){}
    ['startupView','workerLoginView','registerView','expiredView','adminLoginView','adminView','workerView'].forEach(safeHide);
    safeShow('registerView');
    safeHide('logoutBtn');
    setTextSafe('userLine','הרשמה חדשה');
    ['regName','regUsername','regEmail','regPassword','regPassword2'].forEach(function(id){ var el=byId(id); if(el) el.value=''; });
    setHtml('registerMsg','');
    upgradeRegisterButtonsV43();
    return false;
  };
  function upgradeRegisterButtonsV43(){
    var view=byId('registerView'); if(!view) return;
    var back=[].slice.call(view.querySelectorAll('button')).find(function(b){ return String(b.textContent||'').trim()==='חזרה'; });
    if(back){ back.type='button'; back.onclick=function(ev){ if(ev&&ev.preventDefault)ev.preventDefault(); return window.showWorkerLogin(); }; }
    var reg=[].slice.call(view.querySelectorAll('button')).find(function(b){ return String(b.getAttribute('onclick')||'').includes('registerWorker'); });
    if(reg){ reg.type='button'; reg.textContent='פתח משתמש ניסיון'; }
  }
  window.addEventListener('load', upgradeRegisterButtonsV43);
  document.addEventListener('click', function(){ setTimeout(upgradeRegisterButtonsV43,30); });

  async function createPrimaryAuthForSelfV43(username,password,name,recoveryEmail){
    if(!firebaseAuthReadyV43()) throw new Error('Firebase Auth לא נטען. רענן את הדף ונסה שוב.');
    var email=authEmailV43(username,recoveryEmail);
    var cred=null, created=false;
    try{
      cred=await auth.createUserWithEmailAndPassword(email,password);
      created=true;
    }catch(e){
      if(e && e.code==='auth/email-already-in-use'){
        cred=await auth.signInWithEmailAndPassword(email,password);
      }else{
        throw e;
      }
    }
    var user=(cred&&cred.user)?cred.user:auth.currentUser;
    if(!user || !user.uid) throw new Error('Firebase Auth לא החזיר UID.');
    try{ await user.updateProfile({displayName:name||username}); }catch(e){}
    return {uid:user.uid,email:email,created:created};
  }

  window.registerWorker = async function(){
    setHtml('registerMsg','');
    setRegisterBusyV43(true);
    try{
      var name=getValSafe('regName'), username=getValSafe('regUsername'), pass=getValSafe('regPassword'), pass2=getValSafe('regPassword2');
      var recoveryEmail=cleanEmailV43(getValSafe('regEmail'));
      if(!name||!username||!pass||!pass2){ setHtml('registerMsg',"<p class='danger'>חובה למלא שם, שם משתמש וסיסמה.</p>"); return; }
      if(recoveryEmail && !validEmailV43(recoveryEmail)){ setHtml('registerMsg',"<p class='danger'>האימייל לא תקין.</p>"); return; }
      if(pass!==pass2){ setHtml('registerMsg',"<p class='danger'>הסיסמאות לא תואמות.</p>"); return; }
      if(pass.length<6){ setHtml('registerMsg',"<p class='danger'>סיסמה חייבת להיות לפחות 6 תווים.</p>"); return; }

      var usernameKey=normalizeV43(username);
      var workerId=workerIdFromUsernameV43(usernameKey);
      var preferredEmail=authEmailV43(username,recoveryEmail);
      setHtml('registerMsg',"<div class='notice'>יוצר משתמש ניסיון...</div>");

      try{
        var existing=await db.collection('workers').doc(workerId).get();
        if(existing.exists){ setHtml('registerMsg',"<p class='danger'>שם המשתמש כבר קיים. בחר שם משתמש אחר.</p>"); return; }
      }catch(e){ /* אחרי Rules קשיחים ייתכן שאין הרשאת בדיקה לפני Auth — ממשיכים. */ }

      var authResult=await createPrimaryAuthForSelfV43(username,pass,name,recoveryEmail);
      var uid=authResult.uid;
      var trialDays=(typeof DEFAULT_TRIAL_DAYS!=='undefined' && DEFAULT_TRIAL_DAYS) ? DEFAULT_TRIAL_DAYS : 90;
      var trialUntil=todayPlusDaysV43(trialDays);
      var now=firebase.firestore.FieldValue.serverTimestamp();
      var workerData={
        name:name, username:username, usernameKey:usernameKey,
        authEmail:authResult.email||preferredEmail, recoveryEmail:recoveryEmail,
        authUid:uid, authReady:true,
        authNote:"נוצר בהרשמה עצמית בגרסה "+APP_VERSION,
        passwordHash:await sha256V43(pass), monthlyGoal:0, active:true,
        selfRegistered:true, subscriptionStatus:'trial', trialDays:trialDays,
        trialUntil:trialUntil, subscriptionUntil:trialUntil,
        createdAt:now, updatedAt:now
      };

      var failed=[];
      setHtml('registerMsg',"<div class='notice'>שומר את המשתמש במערכת...</div>");
      try{
        await db.collection('workers').doc(workerId).set(workerData,{merge:false});
      }catch(e){
        failed.push('workers: '+((e&&e.code)||e.message||e));
      }
      try{
        await db.collection('users').doc(uid).set({uid:uid,role:'worker',workerId:workerId,username:username,name:name,authEmail:workerData.authEmail,recoveryEmail:recoveryEmail,selfRegistered:true,createdAt:now,updatedAt:now},{merge:true});
      }catch(e){ failed.push('users: '+((e&&e.code)||e.message||e)); }
      try{
        await db.collection('usernameLookup').doc(usernameKey).set({workerId:workerId,username:username,usernameKey:usernameKey,authEmail:workerData.authEmail,authUid:uid,active:true,selfRegistered:true,createdAt:now,updatedAt:now},{merge:true});
      }catch(e){ failed.push('usernameLookup: '+((e&&e.code)||e.message||e)); }

      // בדיקה אמיתית: אם מסמך העובד קיים, ההרשמה הצליחה גם אם user/lookup נתקעו חלקית.
      var workerSaved=false;
      try{ var verify=await db.collection('workers').doc(workerId).get(); workerSaved=verify.exists; }catch(e){ workerSaved=!failed.some(function(x){return x.indexOf('workers:')===0;}); }

      if(!workerSaved){
        var txt=failed.join(' | ');
        if(isPermissionErrorV43(txt)) setHtml('registerMsg',"<p class='danger'>Firebase Auth נוצר, אבל Firestore חסם את יצירת העובד. צריך לעדכן הרשאות Firestore או ליצור את העובד דרך האדמין.</p>");
        else setHtml('registerMsg',"<p class='danger'>נוצר Auth אבל שמירת העובד נכשלה: "+(typeof esc==='function'?esc(txt):txt)+"</p>");
        return;
      }

      try{
        session={role:'worker',workerId:workerId,name:name,authUid:uid,authEmail:workerData.authEmail,remember:true,loginAt:Date.now(),expiresAt:null};
        localStorage.setItem('workSession',JSON.stringify(session));
      }catch(e){}

      if(failed.length){
        setHtml('registerMsg',"<div class='notice'>המשתמש נפתח ונשמר ✅<br>תקופת ניסיון עד "+heDateV43(trialUntil)+"<br>היו שדות אבטחה משניים שלא נשמרו, אבל העובד קיים. מעביר למסך העבודה...</div>");
      }else{
        setHtml('registerMsg',"<div class='notice'>המשתמש נפתח בהצלחה ✅<br>תקופת ניסיון עד "+heDateV43(trialUntil)+"<br>מעביר למסך העבודה...</div>");
      }
      setTimeout(function(){
        try{ if(typeof showWorker==='function') showWorker({id:workerId,...workerData}); }
        catch(e){ window.showWorkerLogin(); }
      },650);
    }catch(e){
      setHtml('registerMsg',"<p class='danger'>שגיאה בהרשמה: "+(typeof esc==='function'?esc((e&&e.code)||e.message||String(e)):((e&&e.code)||e.message||String(e)))+"</p>");
    }finally{
      setRegisterBusyV43(false);
    }
  };

  window.cleanupDeprecatedAdminToolsV43 = function(){
    var admin=byId('adminView'); if(!admin) return;
    ['securityToolsV169','selfRegistrationToolsV176','recoveryInfoPanelV178','rulesWarningV185','adminAuthBootstrapPanelV170'].forEach(function(id){ var el=byId(id); if(el&&el.parentNode) el.parentNode.removeChild(el); });
    var bad=['Security Rules','סקיוריטי','סנכרן אבטחה','העתק Rules','העתק Security','תיקון הרשאות','שחזור גישה לעובד','צור/תקן Auth למנהל'];
    [].slice.call(admin.querySelectorAll('.card,.panel,.paywall')).forEach(function(card){
      var txt=String(card.textContent||'');
      if(bad.some(function(t){return txt.includes(t);})){
        // לא מוחקים לוג מערכת רגיל, רק כרטיסי כלים ישנים שמדברים על Rules/שחזור.
        if(!txt.includes('לוג מערכת')){ try{ card.parentNode.removeChild(card); }catch(e){} }
      }
    });
    [].slice.call(admin.querySelectorAll('button')).forEach(function(btn){
      var txt=String(btn.textContent||''); var oc=String(btn.getAttribute('onclick')||'');
      if(bad.some(function(t){return txt.includes(t);}) || oc.includes('copySecurityRules') || oc.includes('manualSyncSecurity') || oc.includes('resetWorkerAccess')){
        try{ btn.parentNode.removeChild(btn); }catch(e){}
      }
    });
  };
  window.addSecurityToolsV169=function(){};
  window.addSelfRegistrationToolsV176=function(){};
  window.addRecoveryInfoPanelV178=function(){};
  window.addRulesWarningV185=function(){};

  var oldShowAdmin=window.showAdmin;
  if(typeof oldShowAdmin==='function'){
    window.showAdmin=async function(){
      var r=await oldShowAdmin.apply(this,arguments);
      setTimeout(window.cleanupDeprecatedAdminToolsV43,0);
      setTimeout(window.cleanupDeprecatedAdminToolsV43,250);
      setTimeout(window.cleanupDeprecatedAdminToolsV43,900);
      return r;
    };
  }
  setInterval(function(){
    if(!byId('adminView') || byId('adminView').classList.contains('hidden')) return;
    window.cleanupDeprecatedAdminToolsV43();
  },1200);
})();
;
/* ===== v4.4: delete workers + restore security rules panel + registration cleanup ===== */
(function(){
  function el(id){ return document.getElementById(id); }
  function ehtml(s){ try{return esc(s)}catch(_){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));} }
  function showMsg(id,html){ var x=el(id); if(x) x.innerHTML=html; }
  function norm44(s){ try{return normalize(s)}catch(_){return String(s||'').trim().toLowerCase();} }
  function workerDocId44(username){ try{return workerIdFromUsername(norm44(username))}catch(_){return 'worker_'+String(norm44(username)).replace(/[^a-z0-9_\-א-ת]/gi,'_');} }
  function authMail44(username,email){ try{return effectiveAuthEmailV168(username,email)}catch(_){ try{return authEmailFromUsername(username)}catch(__){return workerDocId44(username)+'@work-monitor.local';} } }
  function isAdmin44(){ return session && session.role === 'admin'; }

  window.FIRESTORE_RULES_V44 = `rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function signedIn() { return request.auth != null; }
    function userDoc() { return get(/databases/$(database)/documents/users/$(request.auth.uid)); }
    function isAdmin() { return signedIn() && userDoc().data.role == 'admin'; }
    function isWorker(workerId) { return signedIn() && userDoc().data.workerId == workerId; }

    match /settings/{docId} {
      allow read: if true;
      allow write: if isAdmin();
    }

    match /users/{uid} {
      allow read: if isAdmin() || (signedIn() && request.auth.uid == uid);
      allow create, update: if isAdmin() || (signedIn() && request.auth.uid == uid);
      allow delete: if isAdmin();
    }

    match /usernameLookup/{usernameKey} {
      allow read: if true;
      allow create, update: if isAdmin() || (signedIn() && request.resource.data.authUid == request.auth.uid);
      allow delete: if isAdmin();
    }

    match /workers/{workerId} {
      allow read: if isAdmin() || isWorker(workerId) || (signedIn() && resource.data.authUid == request.auth.uid);
      allow create: if isAdmin() || (signedIn() && request.resource.data.authUid == request.auth.uid);
      allow update: if isAdmin() || (signedIn() && resource.data.authUid == request.auth.uid);
      allow delete: if isAdmin();
    }

    match /workEntries/{entryId} {
      allow read: if isAdmin() || (signedIn() && resource.data.authUid == request.auth.uid) || isWorker(resource.data.workerId);
      allow create: if isAdmin() || (signedIn() && request.resource.data.authUid == request.auth.uid) || isWorker(request.resource.data.workerId);
      allow update, delete: if isAdmin() || (signedIn() && resource.data.authUid == request.auth.uid) || isWorker(resource.data.workerId);
    }

    match /priceList/{docId} {
      allow read: if signedIn();
      allow write: if isAdmin();
    }

    match /installTemplates/{docId} {
      allow read: if signedIn();
      allow create: if isAdmin() || signedIn();
      allow update, delete: if isAdmin() || (signedIn() && resource.data.ownerAuthUid == request.auth.uid);
    }

    match /paymentRequests/{docId} {
      allow create: if signedIn();
      allow read, update, delete: if isAdmin() || (signedIn() && resource.data.authUid == request.auth.uid);
    }

    match /appLogs/{docId} {
      allow create: if true;
      allow read, update, delete: if isAdmin();
    }
  }
}`;

  window.copySecurityRulesV169 = async function(){
    var rules = window.FIRESTORE_RULES_V44;
    try{
      await navigator.clipboard.writeText(rules);
      alert('Security Rules v4.4 הועתקו ✅\nFirebase → Firestore Database → Rules → הדבק → Publish');
    }catch(e){
      prompt('העתק את Security Rules v4.4:', rules);
    }
    showMsg('securityToolsMsgV44', "<div class='notice'>Security Rules v4.4 הועתקו ✅</div>");
  };

  window.manualSyncSecurityV44 = async function(){
    if(!isAdmin44()) return alert('צריך להיכנס כאדמין.');
    var msg=el('securityToolsMsgV44'); if(msg) msg.innerHTML="<div class='notice'>מסנכרן נתוני אבטחה...</div>";
    try{
      var snap=await db.collection('workers').get();
      var batch=db.batch();
      var count=0;
      snap.docs.forEach(function(d){
        var w={id:d.id,...d.data()};
        if(w.movedTo) return;
        var usernameKey=norm44(w.usernameKey||w.username||d.id.replace(/^worker_/,''));
        if(usernameKey){
          batch.set(db.collection('usernameLookup').doc(usernameKey),{
            workerId:d.id, username:w.username||usernameKey, usernameKey:usernameKey,
            authEmail:w.authEmail||authMail44(w.username||usernameKey,w.recoveryEmail||''),
            authUid:w.authUid||'', active:w.active!==false,
            updatedAt:firebase.firestore.FieldValue.serverTimestamp()
          },{merge:true});
        }
        if(w.authUid){
          batch.set(db.collection('users').doc(w.authUid),{
            uid:w.authUid, role:'worker', workerId:d.id, username:w.username||usernameKey,
            name:w.name||'', authEmail:w.authEmail||'', recoveryEmail:w.recoveryEmail||'',
            updatedAt:firebase.firestore.FieldValue.serverTimestamp()
          },{merge:true});
        }
        count++;
      });
      await batch.commit();
      if(msg) msg.innerHTML="<div class='notice'>סנכרון אבטחה הסתיים ✅ עודכנו "+count+" עובדים.</div>";
      if(typeof loadWorkers==='function') await loadWorkers();
    }catch(e){
      if(msg) msg.innerHTML="<p class='danger'>שגיאה בסנכרון אבטחה: "+ehtml((e&&e.code)||e.message||e)+"</p>";
    }
  };

  window.cleanupDeprecatedAdminToolsV43 = function(){};
  window.addSecurityToolsV169 = window.addSecurityToolsV44 = function(){
    var admin=el('adminView'); if(!admin || el('securityToolsV44')) return;
    var card=document.createElement('div');
    card.id='securityToolsV44';
    card.className='card panel';
    card.innerHTML=`
      <div class="cal-head"><h2>🔒 Security Rules והרשאות</h2><button class="btn-green" onclick="manualSyncSecurityV44()">סנכרן אבטחה</button></div>
      <p>השתמש בזה כשיש שגיאת הרשאות בהרשמה/יצירת עובד. קודם סנכרן אבטחה, אחר כך העתק Rules ופרסם ב־Firebase.</p>
      <div class="actions"><button class="btn-light" onclick="copySecurityRulesV169()">העתק Security Rules v4.4</button></div>
      <div id="securityToolsMsgV44"></div>`;
    var workersCard=el('workersList');
    if(workersCard && workersCard.closest('.card')) admin.insertBefore(card, workersCard.closest('.card'));
    else admin.appendChild(card);
  };

  async function deleteQueryBatch44(collection, field, value){
    var snap=await db.collection(collection).where(field,'==',value).get();
    if(snap.empty) return 0;
    var batch=db.batch(), c=0;
    snap.docs.forEach(function(d){ batch.delete(d.ref); c++; });
    await batch.commit();
    return c;
  }

  window.deleteWorkerCompletely = async function(workerId){
    if(!isAdmin44()) return alert('מחיקת עובד מלאה זמינה רק לאדמין.');
    var w=(workers||[]).find(x=>x.id===workerId);
    if(!w){
      try{ var d=await db.collection('workers').doc(workerId).get(); if(d.exists) w={id:d.id,...d.data()}; }catch(e){}
    }
    var name=(w&&w.name)||workerId;
    var usernameKey=norm44((w&&w.usernameKey)||(w&&w.username)||workerId.replace(/^worker_/,''));
    var msg='למחוק לגמרי את העובד '+name+'?\n\nזה ימחק מהמסד:\n- כרטיס עובד\n- usernameLookup\n- users role אם קיים\n- כל העבודות שלו\n- תבניות פרטיות שלו\n\nהפעולה בלתי הפיכה.';
    if(!confirm(msg)) return;
    if(!confirm('אישור אחרון: למחוק לצמיתות?')) return;
    try{
      var deletedEntries=0, deletedTemplates=0;
      try{ deletedEntries=await deleteQueryBatch44('workEntries','workerId',workerId); }catch(e){ console.warn(e); }
      try{ deletedTemplates=await deleteQueryBatch44('installTemplates','ownerWorkerId',workerId); }catch(e){ console.warn(e); }
      var batch=db.batch();
      batch.delete(db.collection('workers').doc(workerId));
      if(usernameKey) batch.delete(db.collection('usernameLookup').doc(usernameKey));
      if(w && w.authUid) batch.delete(db.collection('users').doc(w.authUid));
      await batch.commit();
      alert('העובד נמחק מהמסד ✅\nעבודות שנמחקו: '+deletedEntries+'\nתבניות פרטיות שנמחקו: '+deletedTemplates+'\nשים לב: משתמש Firebase Auth עצמו לא נמחק מה-Authentication דרך הדפדפן, אבל הוא כבר לא מחובר למסד.');
      if(typeof loadWorkers==='function') await loadWorkers();
    }catch(e){
      alert('שגיאה במחיקת עובד: '+((e&&e.code)||e.message||e));
    }
  };

  var oldLoadWorkers44=window.loadWorkers;
  if(typeof oldLoadWorkers44==='function'){
    window.loadWorkers=async function(){
      await oldLoadWorkers44.apply(this,arguments);
      try{
        document.querySelectorAll('#workersList .item').forEach(function(row){
          if(row.querySelector('[data-delete-worker-full="1"]')) return;
          var txt=row.textContent||'';
          var m=txt.match(/ID:\s*([^\s]+)/);
          var workerId=m?m[1]:'';
          if(!workerId) return;
          var actions=row.querySelector('.actions')||row;
          var b=document.createElement('button');
          b.className='btn-red'; b.dataset.deleteWorkerFull='1'; b.textContent='מחק לגמרי';
          b.onclick=function(){ deleteWorkerCompletely(workerId); };
          actions.appendChild(b);
        });
      }catch(e){ console.warn('add delete buttons failed',e); }
    };
  }

  // הרשמה עצמית: אם Auth נוצר אבל Firestore חסום, נותנים הודעה נכונה ולא משאירים מצב לא ברור.
  var oldRegister44=window.registerWorker;
  if(typeof oldRegister44==='function'){
    window.registerWorker=async function(){
      await oldRegister44.apply(this,arguments);
      var msg=el('registerMsg');
      if(msg && /Firebase Auth נוצר.*Firestore חסם|Firestore חסם את יצירת העובד/.test(msg.textContent||'')){
        msg.innerHTML = "<p class='danger'>Firebase Auth נוצר, אבל Firestore חסם את יצירת העובד. זה לא בעיה בטופס — צריך להיכנס לאדמין, לפתוח Security Rules והרשאות, להעתיק Rules v4.4, לפרסם ב־Firebase ואז לנסות שוב. אם העובד כבר מופיע באדמין אפשר למחוק אותו לגמרי וליצור מחדש.</p>";
      }
    };
  }

  var oldShowAdmin44=window.showAdmin;
  if(typeof oldShowAdmin44==='function'){
    window.showAdmin=async function(){
      var r=await oldShowAdmin44.apply(this,arguments);
      setTimeout(function(){ try{ addSecurityToolsV44(); }catch(e){} },50);
      setTimeout(function(){ try{ addSecurityToolsV44(); if(typeof loadWorkers==='function') loadWorkers(); }catch(e){} },500);
      return r;
    };
  }
  window.addEventListener('load',function(){
    try{ if(el('adminView') && !el('adminView').classList.contains('hidden')) addSecurityToolsV44(); }catch(e){}
  });
})();
