      tabs.innerHTML='<button type="button" id="adminFiberPriceBtnV411" class="install-kind-tab-v411" onclick="changeAdminPriceKindV411(\'fiber\')">🔵 מחירון סיב</button><button type="button" id="adminRfPriceBtnV411" class="install-kind-tab-v411" onclick="changeAdminPriceKindV411(\'rf\')">📡 מחירון RF</button>';
