    box.innerHTML='<p>טוען מחירון '+kindLabelV411(selectedAdminKindV411())+'...</p>';
    const all=await getAllPriceDocsV411();
    let items=uniqueActiveSortedV411(all.filter(x=>itemKindV411(x)===selectedAdminKindV411()));
    box.innerHTML=items.length?'':'<p class="muted">אין פריטים פעילים במחירון '+kindLabelV411(selectedAdminKindV411())+'. אפשר להוסיף פריט חדש מלמעלה.</p>';
    items.forEach(item=>{
      const row=document.createElement('div'); row.className='item';
      row.innerHTML=`<div><div class="item-title">${esc(item.name)}</div><div class="item-sub">מחירון: ${kindLabelV411(itemKindV411(item))} · מחיר: ${money(item.price)} · סוג: ${(item.inputMode||'qty')==='check'?'סימון כן/לא':'כמות מספרית'}</div></div><div class="actions"><button class="btn-yellow" onclick="openPriceEdit('${item.id}')">ערוך</button><button class="btn-red" onclick="togglePrice('${item.id}', false)">הסר מהרשימה</button></div>`;
      box.appendChild(row);
    });
