      row.innerHTML=`<div><div class="item-title">${esc(item.name)}</div><div class="item-sub">מחירון: ${kindLabelV411(selectedKindV411())} · מחיר: ${money(item.price)} · ${mode==='check'?'סימון כן/לא':'כמות מספרית'}</div></div>${control}`;
      box.appendChild(row);
