  function compactMoney425(text){
    var raw=String(text||'').replace(/[₪,\s]/g,'');
    var n=Number(raw);
    if(!isFinite(n)) return text;
    if(Math.abs(n)>=10000) return '₪'+Math.round(n/1000)+'K';
    if(Math.abs(n)>=1000){
      var v=(n/1000).toFixed(n%1000===0?0:1).replace('.0','');
      return '₪'+v+'K';
    }
    return '₪'+Math.round(n);
  }
