      var msg=q('workerToolsMsg')||q('settlementMsgV547'); if(msg) msg.innerHTML='<div class="notice">מכין דוח PDF מקצועי לחודש '+safe(month)+'...</div>';
      var allEntries=await allEntriesForMonthV563(month);
